<template><section class="scr-card"><h3>{{ t('race.managedVehicles') }}</h3><EmptyState v-if="!managed.length" :message="t('race.noLineup')" /><div v-else><select v-model="selected" :aria-label="t('race.managedVehicles')"><option v-for="item in managed" :key="item.handle" :value="item.handle">{{ item.name || item.handle }} · {{ item.status }}</option></select><div class="scr-actions"><button type="button" @click="send('focusManagedVehicle')">{{ t('race.focus') }}</button><button type="button" @click="send('respawnManagedVehicle')">{{ t('race.respawn') }}</button><button type="button" @click="send('removeManagedVehicle')">{{ t('common.remove') }}</button></div></div></section></template>
<script setup>import { computed, ref, watch } from "vue"; import { useStores } from "../../stores"; import EmptyState from "../common/EmptyState.vue"; const stores = useStores(); const { t } = stores.i18n; const managed = computed(() => stores.race.state.spawnDirector?.managed || []); const selected = ref(""); watch(managed, list => { if (!list.some(item => item.handle === selected.value)) selected.value = list[0]?.handle || "" }, { immediate: true }); const send = command => selected.value && stores.command.send(command, [selected.value])</script>
